---A configuration to generate a response for GetEffectiveVpcFlowLogsConfig request.
---@class gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfig
---@field connectionLogging? gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfigConnectionLoggingEnum Optional. Configures whether connection logging is enabled for VPC Flow Logs.
---@field subnet? string Traffic will be logged from VMs within the subnetwork. Format: projects/{project_id}/regions/{region}/subnetworks/{name}
---@field interconnectAttachment? string Traffic will be logged from the Interconnect Attachment. Format: projects/{project_id}/regions/{region}/interconnectAttachments/{name}
---@field metadata? gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfigMetadataEnum Configures whether all, none or a subset of metadata fields should be added to the reported VPC flow logs. Default value is INCLUDE_ALL_METADATA.
---@field crossProjectMetadata? gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfigCrossProjectMetadataEnum Determines whether to include cross project annotations in the logs. This field is available only for organization configurations. If not specified in org configs will be set to CROSS_PROJECT_METADATA_ENABLED.
---@field vpnTunnel? string Traffic will be logged from the VPN Tunnel. Format: projects/{project_id}/regions/{region}/vpnTunnels/{name}
---@field scope? gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfigScopeEnum Specifies the scope of the config (e.g., SUBNET, NETWORK, ORGANIZATION..).
---@field metadataFields? gcp.unstable.networkmanagement_v1beta1.StringList Custom metadata fields to include in the reported VPC flow logs. Can only be specified if "metadata" was set to CUSTOM_METADATA.
---@field network? string Traffic will be logged from VMs, VPN tunnels and Interconnect Attachments within the network. Format: projects/{project_id}/global/networks/{name}
---@field state? gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfigStateEnum The state of the VPC Flow Log configuration. Default value is ENABLED. When creating a new configuration, it must be enabled. Setting state=DISABLED will pause the log generation for this config.
---@field aggregationInterval? gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfigAggregationIntervalEnum The aggregation interval for the logs. Default value is INTERVAL_5_SEC.
---@field flowSampling? number The value of the field must be in (0, 1]. The sampling rate of VPC Flow Logs where 1.0 means all collected logs are reported. Setting the sampling rate to 0.0 is not allowed. If you want to disable VPC Flow Logs, use the state field instead. Default value is 1.0.
---@field name? string Unique name of the configuration. The name can have one of the following forms: - For project-level configurations: `projects/{project_id}/locations/global/vpcFlowLogsConfigs/{vpc_flow_logs_config_id}` - For organization-level configurations: `organizations/{organization_id}/locations/global/vpcFlowLogsConfigs/{vpc_flow_logs_config_id}` - For a Compute config, the name will be the path of the subnet: `projects/{project_id}/regions/{region}/subnetworks/{subnet_id}`
---@field filterExpr? string Export filter used to define which VPC Flow Logs should be logged.

---@alias gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfigAggregationIntervalEnum "AGGREGATION_INTERVAL_UNSPECIFIED"|"INTERVAL_5_SEC"|"INTERVAL_30_SEC"|"INTERVAL_1_MIN"|"INTERVAL_5_MIN"|"INTERVAL_10_MIN"|"INTERVAL_15_MIN"

---@alias gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfigConnectionLoggingEnum "CONNECTION_LOGGING_UNSPECIFIED"|"CONNECTION_LOGGING_ENABLED"|"CONNECTION_LOGGING_DISABLED"

---@alias gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfigCrossProjectMetadataEnum "CROSS_PROJECT_METADATA_UNSPECIFIED"|"CROSS_PROJECT_METADATA_ENABLED"|"CROSS_PROJECT_METADATA_DISABLED"

---@alias gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfigList gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfig[]

---@alias gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfigMetadataEnum "METADATA_UNSPECIFIED"|"INCLUDE_ALL_METADATA"|"EXCLUDE_ALL_METADATA"|"CUSTOM_METADATA"

---@alias gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfigScopeEnum "SCOPE_UNSPECIFIED"|"SUBNET"|"COMPUTE_API_SUBNET"|"NETWORK"|"VPN_TUNNEL"|"INTERCONNECT_ATTACHMENT"|"ORGANIZATION"

---@alias gcp.unstable.networkmanagement_v1beta1.EffectiveVpcFlowLogsConfigStateEnum "STATE_UNSPECIFIED"|"ENABLED"|"DISABLED"

